INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('d01', 'deep', 'When did you last cry alone?', '마지막으로 혼자 운 게 언제였어요?', true, 1) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('d02', 'deep', 'Take turns sharing 5 things you like about each person in the group.', '그룹의 각 사람에 대해 좋아하는 점 5가지를 번갈아가며 말해보세요.', true, 2) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('d03', 'deep', 'How do you feel about your relationship with your mother (or father)?', '당신은 어머니(또는 아버지)와의 관계에 대해 어떻게 느끼세요?', true, 3) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('d04', 'deep', 'Take turns saying 3 sentences starting with "We". e.g., "We are all sitting here feeling..."', '"우리"로 시작하는 문장 3개를 번갈아가며 말해보세요. 예: "우리 모두 여기 앉아서... 느끼고 있어요."', true, 4) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('d05', 'deep', 'Complete: "I wish I had someone to share..."', '문장 완성: "나는 누군가와 나누고 싶어요..."', true, 5) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('d06', 'deep', 'If you were to become close friends with someone in this group, what should they know about you?', '이 그룹의 누군가와 가까운 친구가 된다면 그 사람이 당신에 대해 뭘 알아야 할까요?', true, 6) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('d07', 'deep', 'Tell someone in the group what you like about them (be honest, share something you might not say to a stranger).', '그룹의 누군가에게 당신이 그 사람에 대해 좋아하는 점을 말해주세요 (솔직하게, 낯선 사람에게는 말하지 않을 만한 것을 나누세요).', true, 7) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('d08', 'deep', 'Share an embarrassing moment from your life.', '인생에서 부끄러웠던 순간을 나눠보세요.', true, 8) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('d09', 'deep', 'What have you been afraid to talk about with anyone? (share only if comfortable)', '누구와도 이야기하기 두려웠던 게 뭐예요? (편할 때만 나누세요)', false, 9) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('d10', 'deep', 'What do you want people to remember you for after you''re gone?', '당신이 떠난 후 사람들이 당신을 어떻게 기억하기를 원하세요?', false, 10) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('d11', 'deep', 'Is there someone in your life you should apologize to?', '사과해야 할 사람이 인생에 있나요?', false, 11) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('d12', 'deep', 'Is there someone in your life you should forgive?', '인생에서 용서해야 할 사람이 있나요?', false, 12) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('d13', 'deep', 'If you knew you would die tomorrow and could contact one person, who would you call and what would you say?', '내일 죽는다는 걸 알고 한 사람에게 연락할 수 있다면 누구에게 전화해서 무엇을 말하겠어요?', true, 13) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('d14', 'deep', 'What, if anything, is too serious to joke about?', '농담해서는 안 될 만큼 진지한 일이 있다면 뭐예요?', true, 14) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('d15', 'deep', 'What''s the loneliest you''ve ever felt?', '지금까지 가장 외로웠던 때는 언제예요?', false, 15) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('d16', 'deep', 'What would you do differently if you knew nobody would judge you?', '아무도 판단하지 않는다는 걸 안다면 뭘 다르게 하시겠어요?', false, 16) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('d17', 'deep', 'When have you felt truly seen by someone?', '누군가에게 진심으로 이해받았다고 느낀 순간은 언제였어요?', false, 17) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('d18', 'deep', 'What part of yourself do you struggle to accept?', '자신에게서 받아들이기 어려운 부분은 뭐예요?', false, 18) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('d19', 'deep', 'Have you ever felt like you were meant to do something specific with your life? What is it?', '인생에서 특정한 뭔가를 하도록 정해져 있다고 느낀 적이 있나요? 그게 뭐예요?', false, 19) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('d20', 'deep', 'If your house was burning and you could only save one thing, what would it be and why?', '집이 불타고 있고 한 가지만 구할 수 있다면 무엇을 구하고 왜인가요?', true, 20) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('d21', 'deep', 'Of all the people in your family, whose death would disturb you most? Why? (sensitive — skip if uncomfortable)', '가족 중 누구의 죽음이 가장 마음 아플까요? 왜요? (민감함 — 편하지 않으면 넘어가세요)', true, 21) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('d22', 'deep', 'Have you truly forgiven yourself for something?', '자신을 진정으로 용서한 적이 있나요?', false, 22) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('d23', 'deep', 'What''s a truth you''ve never told anyone but wish you could?', '누구에게도 말하지 못했지만 말하고 싶은 진실이 있나요?', false, 23) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('d24', 'deep', 'What does love mean to you now, versus 10 years ago?', '사랑이 지금 당신에게 어떤 의미인가요, 10년 전과 비교해서?', false, 24) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('d25', 'deep', 'Share one thing about your identity (culture, background, values) that you rarely talk about but is important to you.', '자주 이야기하지 않지만 당신에게 중요한 정체성(문화, 배경, 가치관)의 한 가지 측면을 나눠보세요.', false, 25) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('g01', 'getting_real', 'If a crystal ball could tell you the truth about yourself, your life, or the future — what would you want to know?', '수정 구슬이 당신 자신, 인생, 또는 미래에 대한 진실을 알려줄 수 있다면 뭘 알고 싶으세요?', true, 1) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('g02', 'getting_real', 'Is there something you''ve dreamed of doing for a long time? Why haven''t you done it?', '오랫동안 하고 싶었던 게 있나요? 왜 아직 안 했어요?', false, 2) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('g03', 'getting_real', 'What''s the greatest accomplishment of your life so far?', '지금까지 인생에서 가장 큰 성취는 뭐예요?', true, 3) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('g04', 'getting_real', 'What do you value most in a friendship?', '우정에서 가장 중요하게 여기는 게 뭐예요?', true, 4) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('g05', 'getting_real', 'What''s the biggest culture shock you experienced when moving here?', '여기로 오면서 겪은 가장 큰 문화 충격은 뭐였어요?', false, 5) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('g06', 'getting_real', 'What''s one thing from your home country you deeply miss?', '고향에서 정말 그리운 게 하나 있다면 뭐예요?', false, 6) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('g07', 'getting_real', 'What''s something you had to give up when you moved to Korea?', '한국으로 오면서 포기해야 했던 게 있나요?', false, 7) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('g08', 'getting_real', 'What''s your most treasured memory?', '가장 소중히 여기는 기억은 뭐예요?', true, 8) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('g09', 'getting_real', 'What''s your most difficult memory to talk about? (optional — skip if not comfortable)', '이야기하기 가장 어려운 기억은 뭐예요? (선택 사항 — 편하지 않으시면 넘어가세요)', true, 9) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('g10', 'getting_real', 'If you knew you had only one year left, would you change anything about how you live?', '1년밖에 남지 않았다는 걸 안다면 지금 사는 방식을 바꾸시겠어요?', false, 10) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('g11', 'getting_real', 'What does home mean to you?', '당신에게 "집"이란 어떤 의미예요?', false, 11) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('g12', 'getting_real', 'What''s your most treasured relationship?', '가장 소중한 관계는 뭐예요?', true, 12) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('g13', 'getting_real', 'What''s something you believed as a child that turned out to be untrue?', '어렸을 때 믿었지만 사실이 아니었던 게 있나요?', false, 13) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('g14', 'getting_real', 'What''s a fear you''ve had to overcome?', '극복해야 했던 두려움은 뭐였어요?', false, 14) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('g15', 'getting_real', 'What role does your family play in your life today?', '오늘 당신의 삶에서 가족은 어떤 역할을 하나요?', false, 15) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('g16', 'getting_real', 'When was the last time you cried in front of someone?', '마지막으로 다른 사람 앞에서 운 게 언제였어요?', false, 16) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('g17', 'getting_real', 'What was your childhood like?', '어린 시절은 어땠어요?', false, 17) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('g18', 'getting_real', 'What''s a lesson you had to learn the hard way?', '힘든 방법으로 배워야 했던 교훈이 있나요?', false, 18) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('g19', 'getting_real', 'How has moving to Korea changed you?', '한국으로 이주하면서 당신은 어떻게 변했어요?', false, 19) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('g20', 'getting_real', 'What''s something you''re proud of that you don''t often share?', '자주 이야기하지 않지만 자랑스럽게 여기는 게 있나요?', false, 20) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('g21', 'getting_real', 'What would you most want to gain from tomorrow?', '내일 하루에서 가장 얻고 싶은 게 뭐예요?', true, 21) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('g22', 'getting_real', 'What does success mean to you personally (not to society)?', '사회가 아닌 당신 개인에게 성공은 어떤 의미예요?', false, 22) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('g23', 'getting_real', 'If you could go back and give your 15-year-old self one piece of advice, what would it be?', '15살의 당신에게 한 가지 조언을 해줄 수 있다면 뭘 말해주시겠어요?', false, 23) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('g24', 'getting_real', 'What friendship in your past do you wish you had kept?', '과거의 우정 중 유지했으면 좋았을 것은 뭐예요?', false, 24) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('g25', 'getting_real', 'What kind of person do you want to become in 5 years?', '5년 후 어떤 사람이 되고 싶으세요?', false, 25) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('w01', 'warmup', 'If you could invite any 3 people (living or historical) to dinner, who would you pick?', '살아있거나 역사적인 인물 중 3명을 저녁 식사에 초대할 수 있다면 누구를 부르시겠어요?', true, 1) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('w02', 'warmup', 'Would you like to be famous? In what way?', '유명해지고 싶으세요? 어떤 분야에서요?', true, 2) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('w03', 'warmup', 'Before making a phone call, do you rehearse what you''ll say? Why?', '전화하기 전에 무슨 말을 할지 미리 연습하시나요? 왜 그런가요?', true, 3) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('w04', 'warmup', 'What would a "perfect day" look like for you?', '당신에게 "완벽한 하루"란 어떤 모습인가요?', true, 4) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('w05', 'warmup', 'When was the last time you sang to yourself? To someone else?', '마지막으로 혼자 노래를 부른 게 언제였나요? 다른 사람 앞에서는요?', true, 5) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('w06', 'warmup', 'If you could live to 90 and keep either the mind or body of a 30-year-old, which would you pick?', '90살까지 살면서 30살의 정신이나 몸 중 하나를 유지할 수 있다면 어떤 걸 선택하시겠어요?', true, 6) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('w07', 'warmup', 'What''s your favorite meal from home?', '고향에서 가장 좋아하는 음식은 뭐예요?', false, 7) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('w08', 'warmup', 'Do you have a secret hunch about how you''ll die?', '자신이 어떻게 죽을지에 대한 예감이 있으신가요?', true, 8) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('w09', 'warmup', 'What''s one Korean word or phrase you love the sound of?', '발음이 좋아서 마음에 드는 한국어 단어나 표현이 있나요?', false, 9) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('w10', 'warmup', 'What''s the strangest thing you''ve eaten?', '지금까지 먹어본 것 중 가장 이상한 음식은 뭐예요?', false, 10) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('w11', 'warmup', 'If you could wake up tomorrow having gained one quality or ability, what would it be?', '내일 아침 한 가지 능력이나 자질을 얻어 깨어난다면 무엇이었으면 좋겠어요?', false, 11) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('w12', 'warmup', 'What''s something small that brings you joy lately?', '요즘 당신에게 작은 행복을 주는 게 뭐예요?', false, 12) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('w13', 'warmup', 'Do you like to plan things or be spontaneous?', '계획을 세우는 걸 좋아하세요, 아니면 즉흥적인 걸 좋아하세요?', true, 13) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('w14', 'warmup', 'What''s your go-to comfort activity when stressed?', '스트레스 받을 때 당신의 안식처가 되는 활동은 뭐예요?', false, 14) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('w15', 'warmup', 'What''s a small thing you''re really good at?', '작지만 정말 잘하는 게 있다면 뭐예요?', true, 15) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('w16', 'warmup', 'If you could instantly become fluent in one language, which one?', '즉시 유창해질 수 있다면 어떤 언어를 선택하시겠어요?', false, 16) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('w17', 'warmup', 'What''s the most beautiful place you''ve ever been?', '지금까지 가본 곳 중 가장 아름다웠던 곳은 어디예요?', false, 17) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('w18', 'warmup', 'Do you have a hidden talent nobody knows about?', '아무도 모르는 숨겨진 재능이 있으세요?', false, 18) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('w19', 'warmup', 'What''s your favorite way to spend a Sunday?', '일요일을 가장 좋아하는 방법으로 보내는 방법은 뭐예요?', false, 19) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('w20', 'warmup', 'If you had to teach a stranger one thing you know well, what would it be?', '낯선 사람에게 당신이 잘 아는 것 한 가지를 가르쳐야 한다면 뭘 가르치시겠어요?', false, 20) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('w21', 'warmup', 'What''s a piece of media (book/film/song) that changed something in you?', '당신을 변화시킨 콘텐츠(책/영화/음악)가 있나요?', false, 21) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('w22', 'warmup', 'What did you want to be when you were 10 years old?', '10살 때 뭐가 되고 싶었어요?', false, 22) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('w23', 'warmup', 'What''s your favorite season and why?', '좋아하는 계절과 그 이유는 뭐예요?', false, 23) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('w24', 'warmup', 'If you could travel anywhere in Korea for one day, where would you go?', '한국에서 하루 동안 어디든 여행할 수 있다면 어디로 가시겠어요?', false, 24) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('w25', 'warmup', 'What made you laugh recently?', '최근에 웃게 만든 게 뭐였어요?', false, 25) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('x01', 'depths', 'Have you ever had a thought so dark you''re afraid to say it out loud?', '입 밖으로 꺼내기 두려운 어두운 생각을 해본 적이 있나요?', false, 1) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('x02', 'depths', 'If you could delete one year of your life, which year would it be and why?', '인생에서 한 해를 지울 수 있다면 어떤 해를 지우고 왜인가요?', false, 2) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('x03', 'depths', 'Have you ever truly regretted something you did? What was it?', '자신이 한 일을 진심으로 후회한 적이 있나요? 무엇이었어요?', false, 3) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('x04', 'depths', 'Would you rather be feared or loved? Why?', '두려움의 대상이 되고 싶으세요, 사랑받고 싶으세요? 왜요?', false, 4) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('x05', 'depths', 'What''s the most painful truth about yourself that you''ve tried to ignore?', '자신에 대한 가장 아픈 진실 중 애써 외면해온 것은 뭐예요?', false, 5) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('x06', 'depths', 'If you could bring back one person from the dead, who would it be and why?', '죽은 사람 중 한 명을 되살릴 수 있다면 누구를 되살리고 왜인가요?', false, 6) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('x07', 'depths', 'What''s your worst fear about your own future?', '자신의 미래에 대한 가장 큰 두려움은 뭐예요?', false, 7) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('x08', 'depths', 'If you could live without any emotions, would you?', '아무 감정 없이 살 수 있다면 그렇게 하시겠어요?', false, 8) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('x09', 'depths', 'If you could take away one memory from your life, what would it be?', '인생에서 한 가지 기억을 지울 수 있다면 어떤 기억을 지우시겠어요?', false, 9) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('x10', 'depths', 'Would you rather never feel love again or never feel pleasure again?', '다시는 사랑을 느끼지 못하는 것과 기쁨을 느끼지 못하는 것 중 어떤 게 나아요?', false, 10) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('x11', 'depths', 'What''s the most selfish thing you''ve ever done?', '지금까지 한 일 중 가장 이기적이었던 것은 뭐예요?', false, 11) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('x12', 'depths', 'Would you rather be hated for the truth or loved for a lie?', '진실 때문에 미움받는 것과 거짓 때문에 사랑받는 것 중 어떤 걸 선택하시겠어요?', false, 12) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('x13', 'depths', 'Would you rather lose your best friend or your greatest passion in life?', '가장 친한 친구를 잃는 것과 인생에서 가장 큰 열정을 잃는 것 중 어떤 게 더 힘들까요?', false, 13) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('x14', 'depths', 'If you knew you had one week left to live, what would you do that you wouldn''t normally?', '살날이 일주일밖에 남지 않았다는 걸 알면 평소에는 하지 않을 어떤 걸 하시겠어요?', false, 14) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('x15', 'depths', 'What''s the most disturbing thing you''ve ever seen in real life?', '실제로 본 것 중 가장 충격적이었던 건 뭐예요?', false, 15) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('x16', 'depths', 'What''s the worst lie you''ve ever told that people still believe?', '지금도 사람들이 믿고 있는 최악의 거짓말은 뭐예요?', false, 16) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('x17', 'depths', 'What''s the darkest thought you keep coming back to?', '자꾸 떠오르는 가장 어두운 생각은 뭐예요?', false, 17) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('x18', 'depths', 'What''s a version of yourself you''ve had to grieve?', '애도해야 했던 옛 자신의 모습이 있나요?', false, 18) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('x19', 'depths', 'What''s a truth about yourself you''ve never told anyone, but wish had witnesses?', '누구에게도 말하지 않았지만 누군가 목격해주기를 바라는 자신에 대한 진실이 있나요?', false, 19) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('x20', 'depths', 'What did losing something teach you about who you really are?', '무언가를 잃음으로써 자신이 진짜 어떤 사람인지에 대해 무엇을 배웠어요?', false, 20) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('x21', 'depths', 'What part of your childhood are you still healing from?', '어린 시절의 어떤 부분을 아직도 치유하고 있어요?', false, 21) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('x22', 'depths', 'What have you sacrificed to be who you are today?', '지금의 당신이 되기 위해 무엇을 희생했어요?', false, 22) ON CONFLICT DO NOTHING;
INSERT INTO public.conversation_questions (id, set_name, text_en, text_ko, is_aron_original, display_order) VALUES ('x23', 'depths', 'When have you felt most invisible?', '언제 가장 투명한 존재 같다고 느꼈어요?', false, 23) ON CONFLICT DO NOTHING;
